import { WzPropertyType } from "../WzPropertyType.js";
import { WzImageProperty } from "../WzImageProperty.js";
/**
 * @public
 */
export class WzStringProperty extends WzImageProperty {
    constructor(name = '', val = '') {
        super();
        this.name = name;
        this.val = val;
        this.parent = null;
    }
    get propertyType() {
        return WzPropertyType.String;
    }
    dispose() {
        if (this._disposed)
            return;
        this._disposed = true;
    }
    get value() {
        return this.val;
    }
    get wzValue() {
        return this.val;
    }
    setValue(value) {
        this.val = value;
    }
    toString() {
        return this.val;
    }
}
